import{_ as e,o,c as r,a5 as a}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/tools/development-tools-basics.svg",p=JSON.parse('{"title":"開発ツールの基本 — エディター・IDE・デバッガ・プロファイラー","description":"","frontmatter":{"title":"開発ツールの基本 — エディター・IDE・デバッガ・プロファイラー","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"コードを書く、ビルドする、動作を追う、性能を測る場面から、エディター、IDE、コンパイラ、デバッガ、プロファイラーの機能を説明する。","aliases":["IDE","統合開発環境","エディター","エディタ","debugger","デバッガ","profiler","プロファイラ","コード補完","ステップ実行","ウォッチ","コールスタック"],"verification":"MicrosoftのVisual Studio・Visual Studio Code・デバッグ・性能計測の公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"tools/development-tools-basics.md","filePath":"tools/development-tools-basics.md"}'),d={name:"tools/development-tools-basics.md"};function i(n,t,l,u,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="開発ツールの基本-—-エディター・ide・デバッガ・プロファイラー" tabindex="-1">開発ツールの基本 — エディター・IDE・デバッガ・プロファイラー <a class="header-anchor" href="#開発ツールの基本-—-エディター・ide・デバッガ・プロファイラー" aria-label="Permalink to &quot;開発ツールの基本 — エディター・IDE・デバッガ・プロファイラー&quot;">​</a></h1><p>ゲームのコードを書くときは、文字を編集するほか、実行できる形を作り、動きを調べ、重い処理を測ります。こうした作業を助けるソフトウェアが<strong>開発ツール</strong>です。一つのアプリの中から複数の道具を呼び出すこともあります。<a href="https://learn.microsoft.com/en-us/visualstudio/get-started/visual-studio-ide" target="_blank" rel="noreferrer">Visual Studioの開発環境</a></p><h2 id="何をしたいかで機能を見る" tabindex="-1">何をしたいかで機能を見る <a class="header-anchor" href="#何をしたいかで機能を見る" aria-label="Permalink to &quot;何をしたいかで機能を見る&quot;">​</a></h2><table tabindex="0"><thead><tr><th>道具</th><th>主な仕事</th><th>使う場面</th></tr></thead><tbody><tr><td><strong>コードエディター</strong></td><td>ソースコードの文字を編集し、色分けや検索で読み書きを助ける。</td><td>プレイヤーの移動処理を書く。</td></tr><tr><td><strong>コンパイラ</strong></td><td>ソースコードを解析し、次の段階で使うコードへ変換する。</td><td>C++のソースからオブジェクトファイルを作る。</td></tr><tr><td><strong>ビルドツール</strong></td><td>設定や依存関係をもとに、必要な変換・リンクなどを実行する。</td><td>変更したファイルからゲームを作り直す。</td></tr><tr><td><strong>デバッガ</strong></td><td>実行を止めたり進めたりして、値や呼び出しの流れを調べる。</td><td>ダメージ後のHPが想定外になる場所を追う。</td></tr><tr><td><strong>プロファイラー</strong></td><td>実行中の時間、CPU使用、メモリなどを計測する。</td><td>フレームが遅くなった区間と、時間を使った処理を探す。</td></tr></tbody></table><p>IDE（統合開発環境）は編集、ビルド、デバッグなどを一つの作業環境にまとめます。Visual Studioはその一例です。Visual Studio Codeのようなエディターでも、言語の拡張機能や外部ツールを組み合わせれば、補完・ビルド・デバッグの機能を使えます。<a href="https://learn.microsoft.com/en-us/visualstudio/get-started/visual-studio-ide" target="_blank" rel="noreferrer">Visual Studioの構成</a> · <a href="https://code.visualstudio.com/docs/languages/overview" target="_blank" rel="noreferrer">Visual Studio Codeの言語機能</a></p><figure class="study-figure"><img src="'+s+'" alt="編集したソースコードをビルドしてプログラムを実行する。実行中の値と呼び出しはデバッガで追い、CPU時間やメモリはプロファイラーで測る。結果をもとにコードを編集する。" width="760" height="442" loading="lazy"><figcaption>作業に応じて使う機能を変えます。IDEから各ツールを起動する構成もあります。<a href="/study/images/tools/development-tools-basics.svg" target="_blank" rel="noopener noreferrer">開発ツールの図を拡大</a></figcaption></figure><h2 id="書いている途中に助ける機能" tabindex="-1">書いている途中に助ける機能 <a class="header-anchor" href="#書いている途中に助ける機能" aria-label="Permalink to &quot;書いている途中に助ける機能&quot;">​</a></h2><p><strong>コード補完</strong>は、変数や関数の候補を表示します。<strong>定義へ移動</strong>では、使っている名前がどこで宣言・定義されているかを開けます。<strong>参照の検索</strong>は、その名前を使っている場所を探します。名前の変更を参照先へ反映する機能は、<strong>リファクタリング</strong>の一つです。こうした機能は、選んだ言語や拡張機能、プロジェクトの設定に応じて使えます。<a href="https://code.visualstudio.com/docs/editor/intellisense" target="_blank" rel="noreferrer">Visual Studio Codeの補完</a> · <a href="https://code.visualstudio.com/docs/editor/editingevolved" target="_blank" rel="noreferrer">コードの移動と参照検索</a></p><p>エディター上のエラー表示と、ビルド時のエラーには、それぞれ解析元があります。どのファイル・行で、どのツールが出したメッセージかを読みます。ビルドを実行すると、実際に使う設定でコンパイラなどを動かした結果を確認できます。<a href="/study/compilers/source-code-and-execution.html">ソースコードから実行まで</a> · <a href="/study/tools/build/what-is-build.html">ビルドとは何か</a></p><h2 id="値がおかしいときは実行を追う" tabindex="-1">値がおかしいときは実行を追う <a class="header-anchor" href="#値がおかしいときは実行を追う" aria-label="Permalink to &quot;値がおかしいときは実行を追う&quot;">​</a></h2><p>例えばHPが<code>10</code>から<code>7</code>になるはずなのに、<code>4</code>になったとします。HPを更新する行に<strong>ブレークポイント</strong>を置くと、その位置で実行を一時停止できます。<strong>ウォッチ</strong>で変数の値を見て、<strong>ステップ実行</strong>で処理を少しずつ進め、更新が二度行われていないかを確かめます。<a href="https://learn.microsoft.com/en-us/visualstudio/debugger/debugger-feature-tour" target="_blank" rel="noreferrer">Visual Studioのデバッガ</a></p><table tabindex="0"><thead><tr><th>機能</th><th>見るもの</th></tr></thead><tbody><tr><td><strong>ステップイン</strong></td><td>呼び出す関数の中へ入り、処理を追う。</td></tr><tr><td><strong>ステップオーバー</strong></td><td>関数呼び出しを一まとまりとして進め、呼び出し元の続きを追う。</td></tr><tr><td><strong>コールスタック</strong></td><td>現在の関数へ、どの呼び出しを経て到達したか。</td></tr><tr><td><strong>ローカル変数・ウォッチ</strong></td><td>停止位置で読める変数や式の値。</td></tr></tbody></table><p>最適化されたコードでは、変数が保持される場所やソース行との対応が変わることがあります。詳しい確認方法は、<a href="/study/tools/windows/debugger-breakpoints-and-watchpoints.html">ブレークポイント</a>と<a href="/study/tools/build/build-configurations.html">ビルド構成・シンボル</a>へ進みます。<a href="https://learn.microsoft.com/en-us/visualstudio/debugger/how-to-debug-optimized-code" target="_blank" rel="noreferrer">Visual Studioの最適化済みコードのデバッグ</a></p><h2 id="遅いときは時間と量を測る" tabindex="-1">遅いときは時間と量を測る <a class="header-anchor" href="#遅いときは時間と量を測る" aria-label="Permalink to &quot;遅いときは時間と量を測る&quot;">​</a></h2><p><strong>プロファイリング</strong>は、実行中に計測データを集め、時間や資源を使う箇所を調べる作業です。CPU使用率や関数ごとの実行時間、メモリの使用量など、目的に合う計測を選びます。実際のゲームに近いビルド設定と操作をそろえると、変更前後を比べられます。<a href="https://learn.microsoft.com/en-us/visualstudio/profiling/profiling-feature-tour" target="_blank" rel="noreferrer">Visual Studioの性能計測</a></p><p>例えば「CPUが計算していた時間」と「I/Oなどの完了を待っていた時間」では、改善する箇所が変わります。GPUの描画を調べるときは、GPU向けの計測やフレーム解析も使います。デバッガで停止する操作は実行のタイミングを変えるため、通常の実行速度を調べるときは計測用の実行を用意します。<a href="https://learn.microsoft.com/en-us/visualstudio/profiling/choose-performance-tool" target="_blank" rel="noreferrer">計測ツールの選び方</a> · <a href="/study/graphics/optimization/tools.html">GPUの調査ツール</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームタイム</a></p><p>コマンドから道具を呼び出す方法は、<a href="/study/tools/terminal-shell-and-commands.html">ターミナル・シェル・コマンド</a>で扱います。</p><p>CPUの計測結果から関数の実行やスレッドの待ちを調べる方法は、<a href="/study/tools/profiling/cpu-profiling.html">CPU プロファイリング</a>へ進みます。</p>',18)])])}const f=e(d,[["render",i]]);export{p as __pageData,f as default};
